sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var grEvent, grWidget, eventsArray = [];
        var requestBody = request.body.data.HEADER;

        //Mandatory fields check
        var requestData = requestBody;
        if (requestData.messageid == '' || requestData.messageid == undefined) {
            gs.info("Script:el_inbound_event,received request with missing Message ID");
            response.setError(new sn_ws_err.BadRequestError('Missing Message Id'));
            return;
        }
        if (requestData.eventtype == '' || requestData.eventtype == undefined) {
            gs.info("Script:el_inbound_event, invalid event type for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Event Type'));
            return;
        }
        if (requestData.source == '' || requestData.source == undefined) {
            gs.info("Script:el_inbound_event, invalid source for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Source'));
            return;
        }
        if (requestData.objecttype == '' || requestData.objecttype == undefined) {
            gs.info("Script:el_inbound_event, invalid object type for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Object Type'));
            return;
        }
        if (requestData.objectidtype == '' || requestData.objectidtype == undefined) {
            gs.info("Script:el_inbound_event, invalid objct id type for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id Type'));
            return;
        }
        if (requestData.objectversion == '' || requestData.objectversion == undefined) {
            gs.info("Script:el_inbound_event, object version for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Object Version'));
            return;
        }
        if (requestData.eventstatus == '' || requestData.eventstatus == undefined) {
            gs.info("Script:el_inbound_event, invalid event status for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Event Status'));
            return;
        }
        if (requestData.eventdatetime == '' || requestData.eventdatetime == undefined) {
            gs.info("Script:el_inbound_event, invalid event date time for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing Event Date Time'));
            return;
        }
        if (requestData.objectid == '' || requestData.objectid == undefined) {
            gs.info("Script:el_inbound_event, invalid object id for request with Message ID" + requestData.messageid);
            response.setError(new sn_ws_err.BadRequestError('Missing objectid'));
            return;
        }

        grEvent = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
        grEvent.addQuery('messageid', requestData.messageid);
        grEvent.addQuery('source', requestData.source);
        grEvent.query();
        //Checking if record already exists
        if (grEvent.next()) {
            response.setError(new sn_ws_err.BadRequestError('Duplicate Entry.'));
            gs.info("Script:el_inbound_event,received request with duplicate event");
            response.setStatus(400);
            return;
        } else {
            //insert record
            grEvent = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
            grEvent.initialize();
            grEvent.objectid = requestData.objectid;
            grEvent.objectversion = requestData.objectversion;
            grEvent.objecttype = requestData.objecttype;
            grEvent.objectidtype = requestData.objectidtype;
            grEvent.eventstatus = requestData.eventstatus;
            grEvent.eventdatetime = requestData.eventdatetime;
            grEvent.eventdatetime_integer = new GlideDateTime(requestData.eventdatetime).getNumericValue();
            grEvent.source = requestData.source;
            grEvent.messageid = requestData.messageid;
            grEvent.eventtype = requestData.eventtype;
            grEvent.additional_attributes = requestData.additionalattributes;
            var queueid = setQueue(requestData.objectid);
            if (!isNaN(queueid))
                grEvent.queue = parseInt(queueid).toString();

            //MSSOTIQUBE-1246 if insert successfull, Send response code 200; else log error and trigger xmatter alert, respond error to EL
            if (!grEvent.insert()) {
                gs.error('Equities Event Inbound record insert failed in el_inbound_event, event messageid:' + requestData.messageid + ', objectid:' + requestData.objectid + ', eventstatus:' + requestData.eventstatus);
                var failureDescription = "Equities Event Inbound record insert failed in el_inbound_event, event messageid:" + requestData.messageid + " objectid - " + requestData.objectid + " eventstatus - " + requestData.eventstatus;
                var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');
                response.setStatus(500);
                eventsArray.push({
                    'messageId': requestData.messageid,
                    'errorMessage': 'Record Not Inserted Properly.',
                    'status': 'failure'
                });
            } else {
                eventsArray.push({
                    'status': 'event has been successfully processed'
                });
            }
            response.setBody(eventsArray);
            return;
        }

    } catch (error) {
        //MSSOTIQUBE-1544 adjust error description and uplift the severity
		gs.error("Unexpected error from scripted rest api el_inbound_event, Name: " + error.name + ", Message: " + error.message);
		failureDescription = "iQube Equities unexpected error from Event Inbound scripted rest api el_inbound_event, Name: " + error.name + ", Message: " + error.message;
        createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');
        response.setStatus(500);
		response.setBody({
            'errorMessage': 'unexpected error Name: ' + error.name + 'Message: ' + error.message,
            'status': 'failure'
        });
    }

    function setQueue(objId) {
        var reg = new RegExp("^[0-9]{11}"); //Regex to find first 11 digits at the start of the string
        var objInt = Number(objId.toString().match(reg));
        var queue = (objInt % 24) + 1;
        return queue;
    }
})(request, response);
